# EAFP: single lookup + tight try/else/finally
def parse_timeout(cfg: dict[str, str]) -> float:
    try:
        raw = cfg["timeout"]
        seconds = float(raw)
    except (KeyError, ValueError) as err:
        raise ValueError(f"Invalid timeout config: {err}") from err
    else:
        return seconds
    finally:
        pass  # always runs for resource teardown

class ConfigError(Exception):
    """Base error for configuration failures."""

class MissingKeyError(ConfigError):
    def __init__(self, key: str) -> None:
        super().__init__(f"Missing required key: {key}")
        self.key = key

try:
    val = env["API_PORT"]
except KeyError as err:
    raise MissingKeyError("API_PORT") from err

