from typing import Protocol, runtime_checkable

@runtime_checkable
class PricingRule(Protocol):
    def apply(self, subtotal: float) -> float: ...

class FlatCoupon:
    def __init__(self, amount: float) -> None:
        self.amount = amount
    def apply(self, subtotal: float) -> float:
        return max(0.0, subtotal - self.amount)

