class CountUp:
    def __init__(self, limit: int) -> None:
        self.cur, self.limit = 0, limit
    def __iter__(self):
        return self
    def __next__(self) -> int:
        if self.cur >= self.limit:
            raise StopIteration
        self.cur += 1
        return self.cur

def flatten(items):
    for x in items:
        if isinstance(x, list):
            yield from flatten(x)
        else:
            yield x

